-- ============================================================
-- Seed Data: Tables, Categories & Items with In-Database Images
-- Images are stored directly as Base64 Data in Menu_Items table
-- ============================================================

-- 1. Insert Restaurant Tables (Tables 1 through 10)
ON CONFLICT ("TABLE_ID") DO UPDATE
SET
  "TABLE_NUM" = EXCLUDED."TABLE_NUM",
  "STATUS" = EXCLUDED."STATUS",
  "GUEST_CAPACITY" = EXCLUDED."GUEST_CAPACITY";

-- 2. Insert Menu Categories
ON CONFLICT ("CATEGORY_ID") DO UPDATE
SET "CATEGORY_NAME" = EXCLUDED."CATEGORY_NAME";

-- 3. Insert Menu Items with Embedded Base64 Images
ON CONFLICT ("ITEM_ID") DO UPDATE
SET
  "ITEM_NAME" = EXCLUDED."ITEM_NAME",
  "ITEM_PRICE" = EXCLUDED."ITEM_PRICE",
  "ITEM_DESCRIPTION" = EXCLUDED."ITEM_DESCRIPTION",
  "ITEM_IMAGE" = EXCLUDED."ITEM_IMAGE",
  "ITEM_IMAGE_URL" = EXCLUDED."ITEM_IMAGE_URL",
  "ITEM_STATUS" = EXCLUDED."ITEM_STATUS";

-- 4. Reset Sequences
SELECT setval(pg_get_serial_sequence('public."Restaurant_Tables"', 'TABLE_ID'), coalesce(max("TABLE_ID"), 1), max("TABLE_ID") IS NOT NULL) FROM public."Restaurant_Tables";
SELECT setval(pg_get_serial_sequence('public."Menu_Categories"', 'CATEGORY_ID'), coalesce(max("CATEGORY_ID"), 1), max("CATEGORY_ID") IS NOT NULL) FROM public."Menu_Categories";
SELECT setval(pg_get_serial_sequence('public."Menu_Items"', 'ITEM_ID'), coalesce(max("ITEM_ID"), 1), max("ITEM_ID") IS NOT NULL) FROM public."Menu_Items";
